// READ-ONLY. Only GET urls may be built here. Never add a method,
// a body, or any Lokalise write endpoint to this workflow.
const CFG = {
  mode: 'keys',                 // 'projects' | 'languages' | 'keys'
  project_id: '31393214664f295f94dd86.76792605',   // Personality.co
  filter_tags: ''               // e.g. 'z_human'
};

const BASE = 'https://api.lokalise.com/api2';

if (CFG.mode === 'projects') {
  return [{ json: { mode: 'projects', url: BASE + '/projects?limit=100' } }];
}
if (!CFG.project_id) { throw new Error('project_id is required for mode ' + CFG.mode); }
if (CFG.mode === 'languages') {
  return [{ json: { mode: 'languages', url: BASE + '/projects/' + CFG.project_id + '/languages?limit=500' } }];
}
// include_translations=1 is required: the EN source arrives inside the
// translations array, and dropping it returns rows with no source at all.
// filter_translation_lang_ids=640 restricts that array to EN only. 640 is the
// EN source id in every project in this account; on a ~17k-key project the
// unrestricted form returns all 30 locales and the execution OOMs.
// If Lokalise ever rejects 640 for a project it 400s the WHOLE request, which
// Shape surfaces as an entry in errors[] rather than a short clean page.
let qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_translation_lang_ids=640';
if (CFG.filter_tags) { qs += '&filter_tags=' + encodeURIComponent(CFG.filter_tags); }
return [{ json: { mode: 'keys', url: BASE + '/projects/' + CFG.project_id + '/keys?' + qs } }];

// One compact row per key: { k, en, description }.
// Asserts body.keys is an array on every page — a 429 or a scope error comes
// back as a 200-shaped body with no keys array, and silently reporting on
// 0 rows is the worst way for an audit to fail.
const pages = $input.all();
const rows = [];
const errors = [];
let keysSeen = 0, sourceMissing = 0, mode = 'keys', totalCount = null;

for (const p of pages) {
  const r = p.json || {};
  const body = (r.body !== undefined ? r.body : r) || {};
  const status = r.statusCode;
  const h = r.headers || {};
  if (h['x-pagination-total-count']) { totalCount = Number(h['x-pagination-total-count']); }

  if (body.projects) {
    mode = 'projects';
    for (const pr of body.projects) {
      rows.push({ k: pr.project_id, en: pr.name, description: String((pr.statistics && pr.statistics.keys_total) || '') });
    }
    continue;
  }
  if (body.languages) {
    mode = 'languages';
    for (const l of body.languages) { rows.push({ k: String(l.lang_id), en: l.lang_iso, description: l.lang_name }); }
    continue;
  }
  if (!Array.isArray(body.keys)) {
    errors.push({ statusCode: status, body: JSON.stringify(body).slice(0, 300) });
    continue;
  }
  for (const key of body.keys) {
    keysSeen++;
    const tr = Array.isArray(key.translations) ? key.translations : [];
    const en = tr.find(function (t) { return t.language_iso === 'en'; });
    const name = typeof key.key_name === 'object' ? (key.key_name.web || key.key_name.other || '') : key.key_name;
    if (!en || en.translation === undefined || en.translation === null || en.translation === '') { sourceMissing++; continue; }
    rows.push({ k: name, en: en.translation, description: key.description || '' });
  }
}

// server_total is what the API says exists. Compare it against rows_kept before
// trusting any report: a short page that looks clean is the failure mode this
// whole workflow is built to avoid.
const out = { mode: mode, keys_seen: keysSeen, rows_kept: rows.length, server_total: totalCount, source_missing: sourceMissing, pages: pages.length, errors: errors, rows: rows };
if (totalCount !== null && mode !== 'keys' && rows.length !== totalCount) {
  out.warning = 'server says ' + totalCount + ' but ' + rows.length + ' came back — do not report as complete';
}
return [{ json: out }];
